CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255), email VARCHAR(255) UNIQUE, password VARCHAR(255));
CREATE TABLE IF NOT EXISTS parking_spaces (id BIGINT AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT, address VARCHAR(255), latitude DECIMAL(10, 8), longitude DECIMAL(11, 8), vehicle_types VARCHAR(255), price_per_hour DECIMAL(10, 2), capacity INT, available_from TIME, available_to TIME, notes VARCHAR(255), model_type VARCHAR(255));
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE parking_spaces;
TRUNCATE TABLE users;
SET FOREIGN_KEY_CHECKS = 1;
